204	/// Cancels a task under way, from its Cancel button: see
205	/// [`PromptMode::cancel_task`].
206	struct Cancel {
207	    /// Set once it is cancelled, for what compiles it, off the main thread.
208	    cancelled: Arc<AtomicBool>,
209	    /// Wakes what is sending it, to end it straight away.
210	    signal: Option<oneshot::Sender<()>>,
211	    /// Stops its run, once it has one.
212	    stop: Option<harness::Stop>,
213	}
214	
215	impl Cancel {
216	    fn cancel(&mut self) {
217	        self.cancelled.store(true, Ordering::SeqCst);
218	        if let Some(stop) = &self.stop {
219	            stop.stop();
220	        }
221	        if let Some(signal) = self.signal.take() {
222	            signal.send(()).ok();
223	        }
224	    }
225	}
