377	impl PromptTask {
378	    fn new(text: SharedString) -> Self {
379	        Self {
380	            text,
381	            compiled: None,
382	            reply: Reply::default(),
383	            status: TaskStatus::Compiling,
384	            mode: None,
385	            imported: Vec::new(),
386	            spec_dir: None,
387	            references: referenced_spec::References::default(),
388	            understanding: Understanding::default(),
389	            _understanding_watch: Task::ready(()),
390	            sent: SentAs::default(),
391	            slices_open: false,
392	            cancel: None,
393	            given: None,
394	        }
