397	    /// A task from the history, as it ended: its run's output is replayed
398	    /// through the harness's parser.
399	    fn restore(saved: SavedPrompt) -> Self {
400	        let mut task = Self::new(saved.text.into());
401	        task.mode = anchor_mode(&saved.anchor);
402	        task.sent = SentAs::of(&saved.anchor);
403	        let Some(record) = saved.record else {
404	            task.reply.stop();
405	            task.status = TaskStatus::Unrecorded;
406	            return task;
407	        };
408	        task.given = record.harness().map(|harness| Given {
409	            harness,
410	            system_prompt: record.system_prompt.clone(),
411	        });
412	        if let Some(markdown) = record.user_prompt.clone() {
413	            task.set_compiled(Compiled::new(
414	                saved.anchor.name().to_string().into(),
415	                markdown,
416	            ));
417	        }
418	        for event in record.events() {
419	            task.apply(event);
420	        }
421	        if record.cancelled {
422	            task.cancel();
423	        } else if let Some(error) = record.error {
424	            task.apply(HarnessEvent::Failed(error));
425	        }
426	        task.end();
427	        task
428	    }
429	
430	    /// Compiled, it runs, unless it was cancelled meanwhile.
431	    fn set_compiled(&mut self, compiled: Compiled) {
432	        self.compiled = Some(compiled);
433	        if self.status.is_active() {
434	            self.status = TaskStatus::Running;
435	        }
436	    }
437	
438	    /// Folds a harness event into the task's output and status.
439	    fn apply(&mut self, event: HarnessEvent) {
440	        self.references.apply(&event);
441	        match self.reply.apply(event) {
442	            Some(error) => self.fail(error),
443	            None if self.reply.done && self.status == TaskStatus::Running => {
444	                self.status = TaskStatus::Done
445	            }
446	            None => {}
447	        }
448	    }
449	
450	    fn fail(&mut self, error: String) {
451	        self.reply.push_error(error);
452	        // A task cancelled stays cancelled, whatever its harness says after.
453	        if self.status != TaskStatus::Cancelled {
454	            self.status = TaskStatus::Failed;
455	        }
456	    }
457	
458	    /// Cancels it, keeping the output it had so far: tool calls still running
459	    /// were cancelled with it.
460	    fn cancel(&mut self) {
461	        self.status = TaskStatus::Cancelled;
462	        self.reply.cancel();
463	    }
464	
465	    /// Whether it can be cancelled: it is under way, sent from here.
466	    fn can_cancel(&self) -> bool {
467	        self.status.is_active() && self.cancel.is_some()
468	    }
469	
470	    /// The run is over. One that ended without a result, as when the harness
471	    /// was stopped, failed, and nothing still running in it finished.
472	    fn end(&mut self) {
473	        // Cancelled, what it printed before it stopped is kept, and any call
474	        // in it still running was cancelled with it.
475	        if self.status == TaskStatus::Cancelled {
476	            self.reply.cancel();
477	            return;
478	        }
479	        if self.reply.done {
480	            return;
481	        }
482	        self.reply.stop();
483	        if self.status != TaskStatus::Failed {
484	            self.fail("The harness stopped without a result.".into());
485	        }
486	    }
487	}
