2665	    /// Sends the task at `ix` of `tasks_of` again, as it was sent, in `mode`
2666	    /// when given, rather than the mode it was sent in. A Code task sent to
2667	    /// Spec is sent with what it did (see [`code_task_of`]); a task sent from
2668	    /// Code, resent to Spec, is told the same code task again; a Spec task
2669	    /// sent to Code is told nothing of one.
2670	    fn resend_in(
2671	        &mut self,
2672	        tasks_of: fn(&PromptMode) -> &Vec<PromptTask>,
2673	        ix: usize,
2674	        mode: Option<SendMode>,
2675	        window: &mut Window,
2676	        cx: &mut Context<Self>,
2677	    ) {
2678	        let Some(task) = tasks_of(self).get(ix) else {
2679	            return;
2680	        };
2681	        let (text, sent) = (task.text.to_string(), task.sent.clone());
2682	        let code_task = match mode {
2683	            Some(SendMode::Spec) if sent.mode == Some(SendMode::Code) => Some(code_task_of(task)),
2684	            Some(_) => None,
2685	            None => sent.code_task.clone(),
2686	        };
2687	        let mode = mode
2688	            .or(sent.mode)
