328	        };
329	        // A blank line separates each property from the next.
330	        rest = rest.strip_prefix(&[""]).unwrap_or(rest);
331	        let mut mode = None;
332	        if let Some(key) = rest.first().and_then(|line| line.strip_prefix(MODE_PREFIX)) {
333	            mode = SendMode::from_key(key.trim());
334	            rest = &rest[1..];
335	            rest = rest.strip_prefix(&[""]).unwrap_or(rest);
336	        }
337	        let sliced = rest.first() == Some(&SLICED_LINE);
338	        if sliced {
339	            rest = &rest[1..];
340	            rest = rest.strip_prefix(&[""]).unwrap_or(rest);
341	        }
342	        let mut attached_text = Vec::new();
343	        if rest.first() == Some(&ATTACHED_TEXT_LINE) {
344	            rest = &rest[1..];
