451	/// Adds `text` to `source` as a multi-line escape block at `indent`, which
452	/// Piton keeps exactly as it is. Its fence is three backslashes, or one more
453	/// than any line of the text made only of backslashes, so nothing in the text
454	/// closes it early.
455	fn push_block(source: &mut String, indent: &str, text: &str) {
456	    let fence = "\\".repeat(fence_length(text));
457	    writeln!(source, "{indent}{fence}").ok();
458	    for line in text.split('\n') {
459	        let line = line.trim_end_matches('\r');
460	        if line.is_empty() {
461	            source.push('\n');
462	        } else {
463	            writeln!(source, "{indent}{line}").ok();
464	        }
465	    }
466	    writeln!(source, "{indent}{fence}").ok();
467	}
