469	/// How many backslashes fence `text`'s escape block.
470	fn fence_length(text: &str) -> usize {
471	    text.split('\n')
472	        .map(str::trim)
473	        .filter(|line| !line.is_empty() && line.chars().all(|c| c == '\\'))
474	        .map(|line| line.len() + 1)
475	        .max()
476	        .unwrap_or(0)
477	        .max(3)
478	}
