480	/// The text of an escape block written by [`push_block`] at `indent` at the
481	/// start of `lines`, and the lines after it; `None` when `lines` don't start
482	/// with one.
483	fn read_escaped<'a, 'b>(lines: &'a [&'b str], indent: &str) -> Option<(String, &'a [&'b str])> {
484	    let fence = lines.first()?.strip_prefix(indent)?;
485	    if fence.len() < 3 || !fence.chars().all(|c| c == '\\') {
486	        return None;
487	    }
488	    let close = format!("{indent}{fence}");
489	    let end = 1 + lines[1..].iter().position(|line| *line == close)?;
490	    let text = lines[1..end]
491	        .iter()
492	        .map(|line| line.strip_prefix(indent).unwrap_or(line.trim_start()))
493	        .collect::<Vec<_>>()
494	        .join("\n");
495	    Some((text, &lines[end + 1..]))
496	}
