503	/// The line a quoted string, as earlier versions wrote them, holds.
504	fn unquote(quoted: &str) -> Option<String> {
505	    let inner = quoted.strip_prefix('"')?.strip_suffix('"')?;
506	    let mut line = String::with_capacity(inner.len());
507	    let mut chars = inner.chars();
508	    while let Some(c) = chars.next() {
509	        line.push(if c == '\\' { chars.next()? } else { c });
510	    }
511	    Some(line)
512	}
