10514	    /// Runs prompt mode until `done`, failing after a while.
10515	    fn run_until(
10516	        cx: &mut TestAppContext,
10517	        prompt_mode: &Entity<PromptMode>,
10518	        what: &str,
10519	        done: impl Fn(&PromptMode) -> bool,
10520	    ) {
10521	        let start = std::time::Instant::now();
10522	        while !prompt_mode.read_with(cx, |this, _| done(this)) {
10523	            if start.elapsed() > Duration::from_secs(30) {
10524	                let tasks = prompt_mode.read_with(cx, |this, _| {
10525	                    this.tasks
10526	                        .iter()
10527	                        .map(|task| {
10528	                            let errors: Vec<&String> = task
10529	                                .reply
10530	                                .parts
10531	                                .iter()
10532	                                .filter_map(|part| match part {
10533	                                    ReplyPart::Error(error) => Some(error),
10534	                                    _ => None,
10535	                                })
10536	                                .collect();
10537	                            format!("{} {errors:?}", task.status.label())
10538	                        })
10539	                        .collect::<Vec<_>>()
10540	                });
10541	                panic!("{what} never happened: {tasks:?}");
10542	            }
10543	            cx.run_until_parked();
10544	            std::thread::sleep(Duration::from_millis(20));
10545	        }
10546	    }
